CREATE FUNCTION [F_Split](
@str VARCHAR(MAX),
@delimiter VARCHAR(10),
@Num INT
)
RETURNS VARCHAR(1000)
AS

BEGIN -- SET NOCOUNT ON added to prevent extra result sets from -- interfering with SELECT statements. SET NOCOUNT ON; DECLARE @RowsInserted INT = 0 DECLARE @RowsUpdated INT = 0 DECLARE @RowsToBeInserted INT = 0 DECLARE @RowsToBeUpdated INT = 0 DECLARE @Table Varchar(100) = 'Case' DECLARE @HospitalIdNull INT, @CaseStatusIdNull INT, @CaseTypeIdNull INT, @SpecialityIdNull INT, @PatientIdNull INT
DECLARE @EndTime datetime DECLARE @StartTime datetime, @LoadTime INT SELECT @StartTime=GETDATE()
DROP INDEX IF EXISTS IX_Case_CaseNumber ON dbo.[Case]; DROP INDEX IF EXISTS IX_Case_CollectionDate ON dbo.[Case]; DROP INDEX IF EXISTS IX_Case_RefPatientKey ON dbo.[Case]; --DROP INDEX IF EXISTS IX_Case_RefRequisitionId ON dbo.[Case]; DROP INDEX IF EXISTS IX_Case_RefRequisitionKey ON dbo.[Case]; DROP INDEX IF EXISTS IX_Case_SpecimenYear ON dbo.[Case];
BEGIN TRY IF @FullLoad = 1 BEGIN TRUNCATE TABLE [dbo].[Case] END
DROP INDEX IF EXISTS IDX_SSIS_CaseData_K_REQUISITION_KEY ON dbo.SSIS_CaseData; DROP INDEX IF EXISTS IDX_SSIS_CaseData_K_PAT_KEY ON dbo.SSIS_CaseData; DROP INDEX IF EXISTS IDX_SSIS_CaseData_CASE_LAB_ID ON dbo.SSIS_CaseData; DROP INDEX IF EXISTS IDX_SSIS_CaseData_AP_CASE_STATUS_CD ON dbo.SSIS_CaseData; DROP INDEX IF EXISTS IDX_SSIS_CaseData_CASE_TYPE_ID ON dbo.SSIS_CaseData; DROP INDEX IF EXISTS IDX_SSIS_CaseData_CASE_SUBSPECIALTY_CD ON dbo.SSIS_CaseData;
CREATE INDEX IDX_SSIS_CaseData_K_REQUISITION_KEY on dbo.SSIS_CaseData(CASE_ID); CREATE INDEX IDX_SSIS_CaseData_K_PAT_KEY on dbo.SSIS_CaseData(CASE_PAT_ID); CREATE INDEX IDX_SSIS_CaseData_CASE_LAB_ID on dbo.SSIS_CaseData(CASE_LAB_ID); CREATE INDEX IDX_SSIS_CaseData_AP_CASE_STATUS_CD on dbo.SSIS_CaseData(AP_CASE_STATUS_C); CREATE INDEX IDX_SSIS_CaseData_CASE_TYPE_ID on dbo.SSIS_CaseData(CASE_TYPE_ID); CREATE INDEX IDX_SSIS_CaseData_CASE_SUBSPECIALTY_CD on dbo.SSIS_CaseData(CASE_SUBSPECIALTY_C);
SELECT @HospitalIdNull = HospitalId from dbo.Hospital Where Code = 'NULL' SELECT @CaseStatusIdNull = CaseStatusId from dbo.CaseStatus Where Code = 'NULL' SELECT @CaseTypeIdNull = CaseTypeId from dbo.CaseType Where Code = 'NULL' SELECT @SpecialityIdNull = SpecialtyId from dbo.Specialty Where Code = 'NULL' SELECT @PatientIdNull = PatientId from dbo.Patient Where RefPatientKey = 'NULL'
SELECT @RowsToBeInserted = COUNT(0) From dbo.SSIS_CaseData S Where NOT EXISTS (Select 0 from dbo.[Case] C where S.CASE_ID = C.RefRequisitionId)
SELECT @RowsToBeUpdated = COUNT(0) From dbo.SSIS_CaseData S Where EXISTS (Select 0 from dbo.[Case] C where S.CASE_ID = C.RefRequisitionId)
--Update the CoPath Specialities
IF NOT EXISTS (SELECT 0 FROM [dbo].[Specialty] Where Code = 'OTHER') BEGIN INSERT INTO [dbo].[Specialty] ([ShortName] ,[Code] ,[DESCRIPTION] ,[DataLabReference] ,[SpecialtyCategory] ,[IsActive] ,[CreateDate] ,[CreateBy] ,[UpdateDate] ,[UpdateBy]) VALUES ('Other' ,'OTHER' ,'OTHER' ,-10 ,'' ,1 ,GetDate() ,User ,NULL ,NULL) END
Update ETLCopathSpecialty set specialty_name = 'HN1', specialty_desc = 'Head & Neck 1' Where specialty_name = 'ENT'
Update ETLCopathSpecialty set specialty_name = 'Other', specialty_desc ='OTHER' Where specialty_name in ('BEACHWOOD', 'END', 'GIE')
--Check with Dr.Robertson Update ETLCopathSpecialty set specialty_name = 'GU LARGE' where specialty_name = 'GULARGE' Update ETLCopathSpecialty set specialty_name = 'LYM1' where specialty_name = 'LYM' Update ETLCopathSpecialty set specialty_name = 'GYN BX' where specialty_name = 'GYNX' Update ETLCopathSpecialty set specialty_name = 'BR BX' where specialty_name = 'BRX' Update ETLCopathSpecialty set specialty_name = 'NEU1' where specialty_name = 'NEU' Update ETLCopathSpecialty set specialty_name = 'CYTO NG' where specialty_name = 'CYT' Update ETLCopathSpecialty set specialty_name = 'REFGX' where specialty_name = 'REF GIX'
Update S set CASE_SUBSPECIALTY_C = SP.DataLabReference From SSIS_CaseData S join ETLCopathSpecialty C on S.CASE_NUM = C.[specnum_formatted] join Specialty SP on C.specialty_name = SP.Code or C.specialty_name = SP.ShortName or C.specialty_desc = SP.DESCRIPTION Where S.CASE_SUBSPECIALTY_C is NULL
--select top 100 * from SSIS_CaseData --select top 100 * from SSIS_CaseData --UPDATE Data print 'Update Start'
Update C SET [PatientId] = ISNULL(P.PatientId, @PatientIdNull) ,[HospitalId] = ISNULL(H.HospitalId, @HospitalIdNull) ,[CaseStatusId] = ISNULL(CS.CaseStatusId, @CaseStatusIdNull) ,[CaseTypeId] = ISNULL(CT.CaseTypeId, @CaseTypeIdNull) ,[SpecialtyId] = ISNULL(ST.SpecialtyId, @SpecialityIdNull) ,[SpecimenYear] = ISNULL(YEAR(S.CASE_ACCESSION_DTTM), 0) ,[CaseNumber] = S.CASE_NUM ,[AccessionDate] = S.CASE_ACCESSION_DTTM ,[ReceiveDate] = S.CASE_RECEIVED_DTTM ,[OverdueDate] = S.CASE_OVERDUE_DTTM ,[CollectionDate] = S.CASE_COLL_DTTM ,[SignoutDate] = S.CASE_SIGNOUT_DTTM ,[RefPatientKey] = P.RefPatientKey ,[IsActive] = 1 ,[UpdateDate] = GETDATE() ,[UpdateBy] = USER ,[UploadDate] = GETDATE() from dbo.[Case] C JOIN dbo.SSIS_CaseData S ON S.CASE_ID = C.RefRequisitionId LEFT JOIN dbo.Patient P on S.CASE_PAT_ID = P.RefPatientKey LEFT JOIN dbo.Hospital H on S.CASE_LAB_ID = H.DataLabReference LEFT JOIN dbo.CaseStatus CS on S.AP_CASE_STATUS_C = CS.DataLabReference LEFT JOIN dbo.CaseType CT on S.CASE_TYPE_ID = CT.DataLabReference LEFT JOIN dbo.Specialty ST on S.CASE_SUBSPECIALTY_C = ST.DataLabReference WHERE C.[HospitalId] <> ISNULL(H.HospitalId, @HospitalIdNull) OR C.[CaseStatusId] <> ISNULL(CS.CaseStatusId, @CaseStatusIdNull) OR C.[CaseTypeId] <> ISNULL(CT.CaseTypeId, @CaseTypeIdNull) OR C.[SpecialtyId] <> ISNULL(ST.SpecialtyId, @SpecialityIdNull) OR C.[SpecimenYear] <> ISNULL(YEAR(S.CASE_ACCESSION_DTTM), 0) OR C.[CaseNumber] <> S.CASE_NUM OR C.[AccessionDate] <> S.CASE_ACCESSION_DTTM OR C.[ReceiveDate] <> S.CASE_RECEIVED_DTTM OR C.[OverdueDate] <> S.CASE_OVERDUE_DTTM OR C.[CollectionDate] <> S.CASE_COLL_DTTM OR C.[SignoutDate] <> S.CASE_SIGNOUT_DTTM OR C.[RefPatientKey] <> P.RefPatientKey OR C.[PatientId] <> ISNULL(P.PatientId, @PatientIdNull)
SET @RowsUpdated = @@ROWCOUNT
Update [CASE] SET UploadDate = GETDATE() WHERE UploadDate IS NULL
print 'Update End' --INSERT Data print 'Insert Start' INSERT INTO [dbo].[Case] ([PatientId] ,[HospitalId] ,[CaseStatusId] ,[CaseTypeId] ,[SpecialtyId] ,[SpecimenYear] ,[CaseNumber] ,[AccessionDate] ,[ReceiveDate] ,[OverdueDate] ,[CollectionDate] ,[SignoutDate] ,[RefRequisitionKey] ,[RefRequisitionId] ,[RefPatientKey]
,[IsActive] ,[CreateDate] ,[CreateBy] ,[UpdateDate] ,[UpdateBy] ,[UploadDate]) Select ISNULL(P.PatientId, @PatientIdNull), ISNULL(H.HospitalId, @HospitalIdNull), ISNULL(CS.CaseStatusId, @CaseStatusIdNull), ISNULL(CT.CaseTypeId, @CaseTypeIdNull), ISNULL(ST.SpecialtyId, @SpecialityIdNull), ISNULL(YEAR(S.CASE_ACCESSION_DTTM), 0), S.CASE_NUM, S.CASE_ACCESSION_DTTM, S.CASE_RECEIVED_DTTM, S.CASE_OVERDUE_DTTM, S.CASE_COLL_DTTM, S.CASE_SIGNOUT_DTTM, S.CASE_ID, S.CASE_ID, P.RefPatientKey, 1, GETDATE(), user, NULL, NULL, GETDATE() from dbo.SSIS_CaseData S LEFT JOIN dbo.Patient P on S.CASE_PAT_ID = P.RefPatientKey LEFT JOIN dbo.Hospital H on S.CASE_LAB_ID = H.DataLabReference LEFT JOIN dbo.CaseStatus CS on S.AP_CASE_STATUS_C = CS.DataLabReference LEFT JOIN dbo.CaseType CT on S.CASE_TYPE_ID = CT.DataLabReference LEFT JOIN dbo.Specialty ST on S.CASE_SUBSPECIALTY_C = ST.DataLabReference Where NOT EXISTS (Select 0 from dbo.[Case] C where S.CASE_ID = C.RefRequisitionId)
SET @RowsInserted = @@ROWCOUNT print 'Insert End'
DROP INDEX IF EXISTS IX_Case_CaseNumber ON dbo.[Case]; CREATE INDEX IX_Case_CaseNumber on dbo.[Case](CaseNumber);
DROP INDEX IF EXISTS IX_Case_CollectionDate ON dbo.[Case]; CREATE INDEX IX_Case_CollectionDate on dbo.[Case](CollectionDate);
DROP INDEX IF EXISTS IX_Case_RefPatientKey ON dbo.[Case]; CREATE INDEX IX_Case_RefPatientKey on dbo.[Case](RefPatientKey);
DROP INDEX IF EXISTS IX_Case_RefRequisitionId ON dbo.[Case]; CREATE INDEX IX_Case_RefRequisitionId on dbo.[Case](RefRequisitionId);
DROP INDEX IF EXISTS IX_Case_RefRequisitionKey ON dbo.[Case]; CREATE INDEX IX_Case_RefRequisitionKey on dbo.[Case](RefRequisitionKey);
DROP INDEX IF EXISTS IX_Case_SpecimenYear ON dbo.[Case]; CREATE INDEX IX_Case_SpecimenYear on dbo.[Case](SpecimenYear);
DROP INDEX IF EXISTS IX_Case_UploadDate ON dbo.[Case]; CREATE INDEX IX_Case_UploadDate on dbo.[Case](UploadDate);
--Update the Hospital for Beaker AP Conversion Laboratory cases Declare @BeakerHospitalId INT, @IndianRiverHospitalId INT, @MartinHealthHospitalId INT, @MainCampusHospitalId INT Select @BeakerHospitalId = HospitalId from dbo.Hospital Where ShortName = 'Beaker AP Conversion Laboratory' Select @IndianRiverHospitalId = HospitalId from dbo.Hospital Where ShortName = 'Indian River Hospital Lab' Select @MartinHealthHospitalId = HospitalId from dbo.Hospital Where ShortName = 'Martin Health South Hospital Lab' Select @MainCampusHospitalId = HospitalId from dbo.Hospital Where ShortName = 'Main Campus'
--Select @BeakerHospitalId, @IndianRiverHospitalId, @MartinHealthHospitalId, @MainCampusHospitalId
Update dbo.[Case] set HospitalId = @IndianRiverHospitalId Where CaseNumber like 'SIR[0-9][0-9]%' and HospitalId = @BeakerHospitalId
Update dbo.[Case] set HospitalId = @MartinHealthHospitalId Where CaseNumber like 'SMHS[0-9][0-9]%' and HospitalId = @BeakerHospitalId
Update dbo.[Case] set HospitalId = @MainCampusHospitalId Where CaseNumber LIKE 'SIR[0-9][0-9]%' and HospitalId = @BeakerHospitalId
Update dbo.[Case] set HospitalId = @MainCampusHospitalId Where CaseNumber LIKE 'SU[0-9][0-9]%' and HospitalId = @BeakerHospitalId
Update dbo.[Case] set HospitalId = @MainCampusHospitalId Where CaseNumber LIKE 'S[0-9][0-9]%' and HospitalId = @BeakerHospitalId
--Select * from dbo.[Case] Where CaseNumber LIKE 'SIR[0-9][0-9]%' SET @RowsInserted = @@ROWCOUNT SELECT @EndTime=GETDATE() SET @LoadTime = DATEDIFF(SECOND, @StartTime, @EndTime)
EXEC dbo.P_SSIS_LogMainTable @Table, @RowsToBeInserted, @RowsInserted, @RowsToBeUpdated, @RowsUpdated, 1, '', @LoadTime;
END TRY BEGIN CATCH DECLARE @ERROR VARCHAR(MAX) = ERROR_MESSAGE() SET @RowsInserted = @@ROWCOUNT SELECT @EndTime=GETDATE() SET @LoadTime = DATEDIFF(SECOND, @StartTime, @EndTime) PRINT ERROR_LINE() EXEC dbo.P_SSIS_LogMainTable @Table, @RowsToBeInserted, @RowsInserted, @RowsToBeUpdated, @RowsUpdated, 0, @ERROR, @LoadTime; THROW 50001, @ERROR, 1;
END CATCH END

BEGIN
PRINT 'START' -- SET NOCOUNT ON added to prevent extra result sets from -- interfering with SELECT statements. SET nocount ON; DECLARE @RowsInserted INT = 0 DECLARE @RowsUpdated INT = 0 DECLARE @RowsToBeInserted INT = 0 DECLARE @RowsToBeUpdated INT = 0 DECLARE @Table VARCHAR(100) = 'CaseComment' DECLARE @CommentTypeIdNull INT DECLARE @year INT DECLARE @EndTime datetime DECLARE @StartTime datetime, @LoadTime INT SELECT @StartTime=GETDATE()
IF EXISTS ( SELECT 0 FROM [dbo].[SSIS_CommentPlainText]) BEGIN PRINT 'START' DECLARE @COMMENTDATA TABLE ( [CaseId] [INT] NOT NULL, [CommentTypeId] [INT] NOT NULL, [Text] [VARCHAR](max) NOT NULL, [RefRequistionKey] [VARCHAR](50) NOT NULL, [RefResultKey] [VARCHAR](50) NOT NULL, [RefLabCompName] [VARCHAR](100) NOT NULL, [RefCommentType] [VARCHAR](100) NULL ) --ALTER INDEX IX_CaseComment_CaseId ON [dbo].[CaseComment] DISABLE; --ALTER INDEX IX_CaseComment_CaseId_CommentTypeId ON [dbo].[CaseComment] DISABLE; --ALTER INDEX IX_CaseComment_RefLabCompName ON [dbo].[CaseComment] DISABLE; --ALTER INDEX IX_CaseComment_RefRequistionKey ON [dbo].[CaseComment] DISABLE; --ALTER INDEX IX_CaseComment_RefResultKey ON [dbo].[CaseComment] DISABLE; BEGIN try IF @FullLoad = 1 BEGIN PRINT 'TRUNCATE TABLE' TRUNCATE TABLE [dbo].[CaseComment] END PRINT 'START - SSIS_CommentPlainText CONTAINS ROWS' /* -- Create Indexes on [SSIS_CommentPlainText] DROP INDEX if exists [dbo].[SSIS_CommentPlainText].[idx_SSIS_CommentPlainText_REQUISITION_ID]; DROP INDEX if exists [dbo].[SSIS_CommentPlainText].[idx_SSIS_CommentPlainText_RESULT_ID]; DROP INDEX if exists [dbo].[SSIS_CommentPlainText].[idx_SSIS_CommentPlainText_CommentType]; DROP INDEX if exists [dbo].[SSIS_CommentPlainText].[idx_SSIS_CommentPlainText_CompName]; DROP INDEX if exists [dbo].[SSIS_CommentPlainText].[idx_SSIS_CommentPlainText_REQUISITION_COMPONENT_GROUP_VALUE]; DROP INDEX if exists [dbo].[SSIS_CommentPlainText].[idx_SSIS_CommentPlainText_REQUISITION_CommentType_Comp];
CREATE NONCLUSTERED INDEX [idx_SSIS_CommentPlainText_REQUISITION_ID] ON [dbo].[SSIS_CommentPlainText] ( [REQUISITION_ID] ASC ) CREATE NONCLUSTERED INDEX [idx_SSIS_CommentPlainText_RESULT_ID] ON [dbo].[SSIS_CommentPlainText] ( [RESULT_ID] ASC ) CREATE NONCLUSTERED INDEX [idx_SSIS_CommentPlainText_CommentType] ON [dbo].[SSIS_CommentPlainText] ( [COMMENT_TYPE] ASC ) CREATE NONCLUSTERED INDEX [idx_SSIS_CommentPlainText_CompName] ON [dbo].[SSIS_CommentPlainText] ( [COMP_NAME] ASC ) CREATE NONCLUSTERED INDEX [idx_SSIS_CommentPlainText_REQUISITION_COMPONENT_GROUP_VALUE] ON [dbo].[SSIS_CommentPlainText] ( requisition_id ASC, component_id ASC, group_line ASC, value_line ASC ) CREATE NONCLUSTERED INDEX [idx_SSIS_CommentPlainText_REQUISITION_CommentType_Comp] ON [dbo].[SSIS_CommentPlainText] ( requisition_id ASC, [COMMENT_TYPE] ASC, comp_name ASC
) */ SELECT @CommentTypeIdNull = commenttypeid FROM dbo.commenttype WHERE code = 'NULL' SELECT @RowsToBeInserted = Count(0) FROM dbo.ssis_commentplaintext PRINT '@RowsToBeInserted: ' + casT(@RowsToBeInserted AS varchar) --INSERT Data --DROP INDEX IF EXISTS [dbo].[CaseComment].IX_CaseComment_CaseId; --DROP INDEX IF EXISTS [dbo].[CaseComment].[IX_CaseComment_CommentTypeId]; --DROP INDEX IF EXISTS [dbo].[CaseComment].IX_CaseComment_RefLabCompName; --DROP INDEX IF EXISTS [dbo].[CaseComment].IX_CaseComment_RefRequistionKey; --DROP INDEX IF EXISTS [dbo].[CaseComment].IX_CaseComment_RefResultKey; print 'cursor_year_ Start'
PRINT 'Rank Start -- ' + Cast(@year AS VARCHAR); WITH cte AS ( SELECT rank_res_group, Row_number() OVER(partition BY requisition_id, component_id, group_line, value_line ORDER BY result_id DESC) rank_num FROM ssis_commentplaintext CPT ) UPDATE cte SET rank_res_group = rank_num;
PRINT 'Rank End -- ' + Cast(@year AS VARCHAR)
DECLARE cursor_year_ CURSOR FOR SELECT DISTINCT specimenyear FROM [Case];
OPEN cursor_year_; FETCH next FROM cursor_year_ INTO @year;
WHILE @@FETCH_STATUS = 0 BEGIN ----PRINT 'Rank Start -- ' + Cast(@year AS VARCHAR); ----WITH cte AS ----( ---- SELECT rank_res_group, ---- Row_number() OVER(partition BY requisition_id, component_id, group_line, value_line ORDER BY result_id DESC) rank_num ---- FROM ssis_commentplaintext CPT ---- JOIN dbo.[Case] C ---- ON cpt.requisition_id = c.refrequisitionid ---- WHERE c.specimenyear = @year ) ----UPDATE cte ----SET rank_res_group = rank_num;
----PRINT 'Rank End -- ' + Cast(@year AS VARCHAR) PRINT 'Comment Concat Start -- ' + Cast(@year AS VARCHAR) DELETE FROM @CommentData
PRINT 'Comment Concat Group - Start - ' + Cast(@year AS VARCHAR)
INSERT INTO @CommentData SELECT Max(c.caseid), Max(ct.commenttypeid), String_agg(mult_ln_val_storage, Char(13)+Char(10) ) within GROUP (ORDER BY group_line, value_line) AS mult_ln_val_storage_all, requisition_id, max(result_id), comp_name, comment_type FROM ssis_commentplaintext cpt JOIN dbo.[Case] c ON cpt.requisition_id = c.refrequisitionid JOIN dbo.commenttype ct ON cpt.comment_type = ct.code WHERE c.specimenyear = @year AND --CPT.REQUISITION_ID = 44011522215 AND cpt.rank_res_group = 1 GROUP BY cpt.requisition_id, comment_type, comp_name
PRINT 'Comment Concat Group - End - ' + Cast(@year AS VARCHAR)
--CREATE NONCLUSTERED INDEX idx_CommentData_CaseId_CommentTypeId_CompName ON CommentData (caseid, commenttypeid, reflabcompname); --GROUP BY c.caseid, -- ct.commenttypeid, -- requisition_id, -- comment_type, -- comp_name PRINT 'Comment Concat End -- ' + Cast(@year AS VARCHAR) PRINT 'Update Start -- ' + Cast(@year AS VARCHAR) IF @FullLoad = 0 BEGIN UPDATE cc SET [Text] = cpt.[Text], [RefRequistionKey] = cpt.[RefRequistionKey], [RefResultKey] = cpt.[RefResultKey], [RefLabCompName] = cpt.[RefLabCompName], [RefCommentType] = cpt.[RefCommentType], updatedate = Getdate(), updateby = USER FROM @CommentData CPT JOIN casecomment CC ON cc.caseid = cpt.caseid AND cc.commenttypeid = cpt.commenttypeid AND cpt.reflabcompname = cc.reflabcompname END
SET @RowsInserted = @RowsInserted + @@ROWCOUNT PRINT 'Update End -- ' + Cast(@year AS VARCHAR) PRINT 'Insert Start -- ' + Cast(@year AS VARCHAR) INSERT INTO [dbo].[CaseComment] ( [CaseId] , [CommentTypeId] , [Text] , [RefRequistionKey] , [RefResultKey] , [RefLabCompName] , [RefCommentType] , [CreateDate] , [CreateBy] , [UpdateDate] , [UpdateBy] ) SELECT [CaseId], [CommentTypeId], [Text], [RefRequistionKey], [RefResultKey], [RefLabCompName], [RefCommentType], Getdate(), USER, NULL, NULL FROM @CommentData CPT WHERE NOT EXISTS ( SELECT 0 FROM casecomment CC WHERE cc.caseid = cpt.caseid AND cc.commenttypeid = cpt.commenttypeid AND cpt.reflabcompname = cc.reflabcompname) SET @RowsInserted = @RowsInserted + @@ROWCOUNT PRINT 'Insert End -- ' + Cast(@year AS VARCHAR) FETCH next FROM cursor_year_ INTO @year;
END CLOSE cursor_year_; DEALLOCATE cursor_year_; PRINT '@year: ' + casT(@year AS varchar) print 'cursor_year_ End'
if EXISTS (select i.name from sys.indexes I join sys.tables o ON i.object_id = o.object_id WHERE o.name = 'CaseComment' AND i.name = 'IX_CaseComment_CommentTypeId') BEGIN ALTER INDEX [IX_CaseComment_CommentTypeId] ON [dbo].[CaseComment] rebuild; END ELSE BEGIN CREATE NONCLUSTERED INDEX [IX_CaseComment_CommentTypeId] ON [dbo].[CaseComment] ( [CommentTypeId] ASC ) END
if EXISTS (select i.name from sys.indexes I join sys.tables o ON i.object_id = o.object_id WHERE o.name = 'CaseComment' AND i.name = 'IX_CaseComment_CaseId') BEGIN ALTER INDEX [IX_CaseComment_CaseId] ON [dbo].[CaseComment] rebuild; END ELSE BEGIN CREATE NONCLUSTERED INDEX [IX_CaseComment_CaseId] ON [dbo].[CaseComment] ( CaseId ASC ) END
if EXISTS (select i.name from sys.indexes I join sys.tables o ON i.object_id = o.object_id WHERE o.name = 'CaseComment' AND i.name = 'IX_CaseComment_RefLabCompName') BEGIN ALTER INDEX [IX_CaseComment_RefLabCompName] ON [dbo].[CaseComment] rebuild; END ELSE BEGIN CREATE NONCLUSTERED INDEX [IX_CaseComment_RefLabCompName] ON [dbo].[CaseComment] ( [RefLabCompName] ASC ) END
SET @RowsInserted = @@ROWCOUNT SELECT @EndTime=GETDATE() SET @LoadTime = DATEDIFF(SECOND, @StartTime, @EndTime)
EXEC dbo.P_SSIS_LogMainTable @Table, @RowsToBeInserted, @RowsInserted, @RowsToBeUpdated, @RowsUpdated, 1, '', @LoadTime;
END try BEGIN catch DECLARE @ERROR VARCHAR(MAX) = ERROR_MESSAGE() SET @RowsInserted = @@ROWCOUNT SELECT @EndTime=GETDATE() SET @LoadTime = DATEDIFF(SECOND, @StartTime, @EndTime) PRINT ERROR_LINE() EXEC dbo.P_SSIS_LogMainTable @Table, @RowsToBeInserted, @RowsInserted, @RowsToBeUpdated, @RowsUpdated, 0, @ERROR, @LoadTime; END catch END ELSE BEGIN PRINT 'NO Records to load' SELECT @EndTime=GETDATE() SET @LoadTime = DATEDIFF(SECOND, @StartTime, @EndTime)
EXEC dbo.P_SSIS_LogMainTable @Table, @RowsToBeInserted, @RowsInserted, @RowsToBeUpdated, @RowsUpdated, 1, '', @LoadTime;
END END

BEGIN
DECLARE @RowsInserted INT, @RowsUpdated INT, @CommentTypeIdNull INT DECLARE @Table Varchar(100) = 'CaseCommentEpic';
DECLARE @EndTime datetime DECLARE @StartTime datetime, @LoadTime INT SELECT @StartTime=GETDATE()
BEGIN TRY IF @FullLoad = 1 BEGIN TRUNCATE TABLE [dbo].[CaseCommentEpic] END
--DROP INDEX IF EXISTS [idx_CaseCommentEpic_CaseId] --ON [dbo].[CaseCommentEpic];
--Clear and create index on SSIS_CommentRTFText DROP INDEX IF EXISTS [idx_SSIS_CommentRTFText_CommentType] ON dbo.SSIS_CommentRTFText; DROP INDEX IF EXISTS [idx_SSIS_CommentRTFText_RESULT_LINE] ON dbo.SSIS_CommentRTFText; DROP INDEX IF EXISTS [idx_SSIS_CommentRTFText_REQUISITION_ID] ON dbo.SSIS_CommentRTFText; DROP INDEX IF EXISTS [idx_SSIS_CommentRTFText_RESULT_ID] ON dbo.SSIS_CommentRTFText;
CREATE NONCLUSTERED INDEX [idx_SSIS_CommentRTFText_CommentType] ON [dbo].[SSIS_CommentRTFText] ( [COMMENT_TYPE] ASC )
